<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Two-factor verification - <?php echo htmlspecialchars(SITENAME); ?></title><style>body{font-family:Arial,sans-serif;background:#f1f5f9;display:grid;place-items:center;min-height:100vh;margin:0}.card{background:#fff;padding:32px;border-radius:16px;max-width:420px;width:calc(100% - 48px);box-shadow:0 16px 40px #0f172a18}input,button{box-sizing:border-box;width:100%;padding:12px;margin-top:10px;border-radius:8px}input{border:1px solid #cbd5e1;font-size:1.2rem;letter-spacing:.3rem}.check{display:flex;gap:10px;align-items:center;margin:12px 0}.check input{width:auto;margin:0}.check label{font-size:.95rem}button{border:0;background:#0f766e;color:#fff;font-weight:700}.error{color:#b91c1c}</style></head><body><main class="card"><h1>Two-factor verification</h1><p>Enter the six-digit code from your authenticator app.</p><?php if ($error): ?><p class="error"><?php echo htmlspecialchars($error); ?></p><?php endif; ?><form method="post"><?php echo csrfInput(); ?><label for="code">Verification code</label><input id="code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required autofocus><div class="check"><input id="remember_device" name="remember_device" type="checkbox" value="1" checked><label for="remember_device">Remember this device for <?php echo (int) $rememberDeviceDays; ?> days</label></div><button type="submit">Verify</button></form></main></body></html>
